  'sleep.science': { en: 'Sleep Science', es: 'Ciencia del sueño', fr: 'Science du sommeil', yo: 'Ìmọ̀ Sáyẹ́nsì Oorun', ig: 'Sayensị Ụra', ha: 'Kimiyyar Barci', pcm: 'Sleep Science' },
  'sleep.tip1Title': { en: 'Deep Sleep Goal', es: 'Objetivo de sueño profundo', fr: 'Objectif de sommeil profond', yo: 'Àfojúsùn Oorun Jíjìn', ig: 'Ebumnuche Ụra Miri Emi', ha: 'Manufar Barci Mai Zurfi', pcm: 'Deep Sleep Goal' },
  'sleep.tip1Body': { en: 'Aim for 15-20% of total sleep in deep stage for optimal physical recovery.', es: 'Apunta al 15-20 % del sueño total en fase profunda para una recuperación física óptima.', fr: 'Visez 15 à 20 % du sommeil total en phase profonde pour une récupération physique optimale.', yo: 'Fojúsùn 15-20% oorun àpapọ̀ ní ipele jíjìn fún ìmúpadàbọ̀ ara tó dára jù.', ig: 'Chee 15-20% nke ụra niile na ọkwa miri emi maka mgbake anụ ahụ kacha mma.', ha: 'Yi niyyar 15-20% na jimillar barci a matakin zurfi don ingantaccen farfaɗowar jiki.', pcm: 'Aim for 15-20% of total sleep for deep stage make body recover well.' },
  'sleep.tip2Title': { en: 'REM Importance', es: 'Importancia del REM', fr: 'Importance du REM', yo: 'Pàtàkì REM', ig: 'Mkpa REM', ha: 'Muhimmancin REM', pcm: 'REM Importance' },
  'sleep.tip2Body': { en: '20-25% REM sleep is critical for memory consolidation and learning.', es: 'El 20-25 % de sueño REM es fundamental para la consolidación de la memoria y el aprendizaje.', fr: '20 à 25 % de sommeil REM sont essentiels à la consolidation de la mémoire et à l’apprentissage.', yo: '20-25% oorun REM ṣe pàtàkì fún ìfẹsẹ̀múlẹ̀ ìrántí àti ìkẹ́kọ̀ọ́.', ig: '20-25% ụra REM dị oke mkpa maka nchekwa ncheta na mmụta.', ha: '20-25% na barcin REM yana da matuƙar muhimmanci ga ƙarfafa ƙwaƙwalwa da koyo.', pcm: '20-25% REM sleep dey important for memory and learning.' },
  'sleep.tip3Title': { en: 'Consistency Wins', es: 'La constancia gana', fr: 'La régularité paie', yo: 'Ìdúróṣinṣin Bori', ig: 'Nkwụsi Ike Na-emeri', ha: 'Daidaito Yana Nasara', pcm: 'Consistency Wins' },
  'sleep.tip3Body': { en: 'Going to bed and waking up at the same time daily improves sleep quality by 30%.', es: 'Acostarse y levantarse a la misma hora cada día mejora la calidad del sueño en un 30 %.', fr: 'Se coucher et se lever à la même heure chaque jour améliore la qualité du sommeil de 30 %.', yo: 'Sísùn àti jíjí ní àkókò kan náà lójoojúmọ́ mú ìdára oorun dára sí i nípa 30%.', ig: 'Ịlakpu na iteta n’otu oge kwa ụbọchị na-eme ka ịdị mma ụra dịkwuo mma site na 30%.', ha: 'Kwanciya da farkawa a lokaci ɗaya kullum yana inganta ingancin barci da kashi 30%.', pcm: 'Sleeping and waking up same time everyday dey improve sleep quality by 30%.' },
  'sleep.tip4Title': { en: 'Recovery Metric', es: 'Métrica de recuperación', fr: 'Indicateur de récupération', yo: 'Ìwọ̀n Ìmúpadàbọ̀', ig: 'Metriki Mgbake', ha: 'Ma’aunin Farfaɗowa', pcm: 'Recovery Metric' },
  'sleep.tip4Body': { en: 'Less than 5% awake time indicates undisturbed, restorative sleep.', es: 'Menos del 5 % de tiempo despierto indica un sueño reparador y sin interrupciones.', fr: 'Moins de 5 % de temps éveillé indique un sommeil réparateur et sans interruption.', yo: 'Kéré ju 5% àkókò jíjí túmọ̀ sí oorun tí kò ní ìdíwọ́, tí ó ń mú ara padà.', ig: 'Ihe na-erughị 5% oge ịmụ anya na-egosi ụra na-adịghị enye nsogbu, nke na-eweghachi ike.', ha: 'Ƙasa da kashi 5% na lokacin farkawa yana nuna barci mai farfaɗowa ba tare da damuwa ba.', pcm: 'Less than 5% awake time show say your sleep no get disturbance, e dey restore body.' },
  'sleep.recentSessions': { en: 'Recent Sessions', es: 'Sesiones recientes', fr: 'Sessions récentes', yo: 'Àwọn Àkókò Àìpẹ́', ig: 'Nnọkọ Na-adịbeghị Anya', ha: 'Zaman Kwanan Nan', pcm: 'Recent Sessions' },
