  'workout.tip1Title': { en: 'Rest Days Matter', es: 'Los días de descanso importan', fr: 'Les jours de repos comptent', yo: 'Àwọn Ọjọ́ Ìsinmi Ṣe Pàtàkì', ig: 'Ụbọchị Izu Ike Dị Mkpa', ha: 'Kwanakin Hutawa Suna Da Muhimmanci', pcm: 'Rest Days Matter' },
  'workout.tip1Body': { en: 'Aim for 1-2 rest days per week for optimal muscle recovery and growth.', es: 'Apunta a 1-2 días de descanso por semana para una recuperación y crecimiento muscular óptimos.', fr: 'Prévoyez 1 à 2 jours de repos par semaine pour une récupération et une croissance musculaires optimales.', yo: 'Fojúsùn ọjọ́ ìsinmi 1-2 lọ́sọ̀ọ̀sẹ̀ fún ìmúpadàbọ̀ àti ìdàgbàsókè iṣan tó dára jù.', ig: 'Chee ụbọchị izu ike 1-2 kwa izu maka mgbake na uto akwara kacha mma.', ha: 'Yi niyyar kwanaki 1-2 na hutawa a mako don ingantaccen farfaɗowar tsoka da girma.', pcm: 'Aim for 1-2 rest days per week make your muscle recover and grow well.' },
  'workout.tip2Title': { en: 'Heart Rate Zones', es: 'Zonas de frecuencia cardíaca', fr: 'Zones de fréquence cardiaque', yo: 'Àwọn Agbègbè Ìlù Ọkàn', ig: 'Mpaghara Ọsọ Obi', ha: 'Yankunan Bugun Zuciya', pcm: 'Heart Rate Zones' },
  'workout.tip2Body': { en: 'Train in different HR zones: 70-80% for fat burn, 80-90% for cardio fitness.', es: 'Entrena en diferentes zonas de FC: 70-80 % para quemar grasa, 80-90 % para estado cardiovascular.', fr: 'Entraînez-vous dans différentes zones de FC : 70-80 % pour brûler les graisses, 80-90 % pour le cardio.', yo: 'Ṣe ìdárayá ní àwọn agbègbè HR ọ̀tọ̀ọ̀tọ̀: 70-80% fún ìjó ọ̀rá, 80-90% fún ìlera kádíò.', ig: 'Zụọ n’ime mpaghara HR dị iche iche: 70-80% maka ọkụ abụba, 80-90% maka ahụ ike kadio.', ha: 'Yi horo a yankuna daban-daban na HR: 70-80% don ƙona kitse, 80-90% don lafiyar kardiyo.', pcm: 'Train for different HR zones: 70-80% for fat burn, 80-90% for cardio fitness.' },
  'workout.tip3Title': { en: 'Progressive Overload', es: 'Sobrecarga progresiva', fr: 'Surcharge progressive', yo: 'Ìfikún Díẹ̀díẹ̀', ig: 'Ibu Karịrị Nke Ọma', ha: 'Ƙara Nauyi A Hankali', pcm: 'Progressive Overload' },
  'workout.tip3Body': { en: 'Gradually increase duration or intensity by 5-10% each week for continuous improvement.', es: 'Aumenta gradualmente la duración o intensidad en un 5-10 % cada semana para mejorar continuamente.', fr: 'Augmentez progressivement la durée ou l’intensité de 5 à 10 % chaque semaine pour progresser en continu.', yo: 'Mú ìgbà tàbí ìlera pọ̀si díẹ̀díẹ̀ nípa 5-10% lọ́sọ̀ọ̀sẹ̀ fún ìlọsíwájú tí ń tẹ̀síwájú.', ig: 'Jiri nwayọọ bawanye oge ma ọ bụ ike site na 5-10% kwa izu maka nkwalite na-aga n’ihu.', ha: 'A hankali ƙara tsawo ko ƙarfi da 5-10% kowane mako don ci gaba mai dorewa.', pcm: 'Gradually increase duration or intensity by 5-10% each week make you dey improve.' },
