  'goalsetup.step0.subtitle': { en: "Pick everything that applies — we'll tune your dashboard to match.", es: 'Elige todo lo que corresponda — ajustaremos tu panel para que coincida.', fr: "Choisissez tout ce qui s'applique — nous adapterons votre tableau de bord.", yo: 'Yan gbogbo ohun tó bá yẹ — a ó ṣàtúnṣe dashboard rẹ láti bá a mu.', ig: 'Họrọ ihe niile dabara — anyị ga-ahazi dashboard gị ka ọ dakọọ.', ha: 'Zaɓi duk abin da ya dace — za mu daidaita dashboard ɗinka.', pcm: 'Pick everything wey apply — we go arrange your dashboard to match am.' },
  'goalsetup.step1.title': { en: 'A little about you', es: 'Un poco sobre ti', fr: 'Un peu sur vous', yo: 'Díẹ̀ nípa rẹ', ig: 'Ntakịrị gbasara gị', ha: 'Kaɗan game da kai', pcm: 'Small tori about you' },
  'goalsetup.step1.subtitle': { en: 'This helps us set the right calorie and health targets for you.', es: 'Esto nos ayuda a fijar los objetivos correctos de calorías y salud para ti.', fr: 'Cela nous aide à définir les bons objectifs de calories et de santé pour vous.', yo: 'Èyí ràn wá lọ́wọ́ láti gbé àfojúsùn kalori àti ìlera tó tọ́ kalẹ̀ fún ọ.', ig: 'Nke a na-enyere anyị aka ịtọ ebumnuche calorie na ahụike ziri ezi maka gị.', ha: 'Wannan yana taimaka mana saita madaidaitan manufofin kalori da lafiya a gare ka.', pcm: 'Dis one dey help us set the correct calorie and health target for you.' },
