  'planmeal.defaultGoal': { en: 'General Health & Nutrition', es: 'Salud y nutrición general', fr: 'Santé et nutrition générales', yo: 'Ìlera Gbogbogbòò & Oúnjẹ', ig: 'Ahụike Izugbe & Nri', ha: 'Lafiya da Abinci Gaba ɗaya', pcm: 'General Health & Nutrition' },
  'planmeal.selectMealType': { en: 'Select Your Meal Type', es: 'Selecciona tu tipo de comida', fr: 'Choisissez votre type de repas', yo: 'Yan Irú Oúnjẹ Rẹ', ig: 'Họrọ Ụdị Nri Gị', ha: "Zaɓi Nau'in Abincinka", pcm: 'Select Your Meal Type' },
  'planmeal.selectMealTypeDesc': { en: "Choose the meal you'd like to plan. We'll generate personalized recommendations based on your health profile, dietary needs, and local food availability.", es: 'Elige la comida que quieres planificar. Generaremos recomendaciones personalizadas según tu perfil de salud, necesidades dietéticas y disponibilidad de alimentos locales.', fr: 'Choisissez le repas à planifier. Nous générerons des recommandations personnalisées selon votre profil de santé, vos besoins alimentaires et les aliments locaux disponibles.', yo: 'Yan oúnjẹ tí o fẹ́ ṣètò. A ó ṣẹ̀dá àwọn àbá tí a ṣe àkànṣe lórí ìpìlẹ̀ profaili ìlera rẹ, àìní oúnjẹ, àti wíwà oúnjẹ agbègbè.', ig: 'Họrọ nri ị chọrọ ịhazi. Anyị ga-emepụta aro ahaziri iche dabere na profaịlụ ahụike gị, mkpa nri, na nri obodo dị.', ha: "Zaɓi abincin da kake son tsarawa. Za mu samar da shawarwari na musamman bisa bayanin lafiyarka, bukatun abinci, da samuwar abincin gida.", pcm: 'Choose the meal wey you wan plan. We go create personalized advice based on your health profile, food need, and local food wey dey available.' },
  'planmeal.meal.breakfast': { en: 'Breakfast', es: 'Desayuno', fr: 'Petit-déjeuner', yo: 'Oúnjẹ Àárọ̀', ig: 'Nri Ụtụtụ', ha: 'Karin Kumallo', pcm: 'Breakfast' },
  'planmeal.meal.brunch': { en: 'Brunch', es: 'Brunch', fr: 'Brunch', yo: 'Oúnjẹ Àárín Àárọ̀', ig: 'Nri Etiti Ụtụtụ', ha: 'Brunch', pcm: 'Brunch' },
