  'age.tip.mid2': { en: 'Heart-healthy fats and fiber-rich foods', es: 'Grasas saludables para el corazón y alimentos ricos en fibra', fr: 'Bonnes graisses pour le cœur et aliments riches en fibres', yo: 'Ọ̀rá tó dára fún ọkàn àti oúnjẹ ọlọ́rọ̀ fáìbà', ig: 'Abụba dị mma maka obi na nri jupụtara na fiber', ha: 'Kitse mai kyau ga zuciya da abinci mai fiber', pcm: 'Heart-healthy fats and fiber-rich foods' },
