  'age.tip.senior1': { en: 'Vitamin B12 and D supplementation may be needed', es: 'Puede ser necesario suplementar con vitamina B12 y D', fr: 'Une supplémentation en vitamine B12 et D peut être nécessaire', yo: 'Àfikún vitamin B12 àti D lè jẹ́ dandan', ig: 'Enwere ike ịchọ mgbakwunye vitamin B12 na D', ha: 'Ana iya buƙatar ƙarin vitamin B12 da D', pcm: 'You fit need Vitamin B12 and D supplement' },
