  'goals.tipHeadDaily': { en: 'Daily Tip', es: 'Consejo diario', fr: 'Astuce du jour', yo: 'Ìmọ̀ràn Ojoojúmọ́', ig: 'Ndụmọdụ Kwa Ụbọchị', ha: 'Shawarar Yau da Kullum', pcm: 'Daily Tip' },
  'goals.tipStart': { en: 'Ready to transform your health? Start by setting one achievable goal today!', es: '¿Listo para transformar tu salud? ¡Empieza fijando una meta alcanzable hoy!', fr: "Prêt à transformer votre santé ? Commencez par fixer un objectif atteignable aujourd'hui !", yo: 'Ṣé o ti ṣetán láti yí ìlera rẹ padà? Bẹ̀rẹ̀ nípa gbígbé àfojúsùn tí ó ṣeéṣe kalẹ̀ lónìí!', ig: 'Ị dịla njikere ịgbanwe ahụike gị? Malite site na ịtọ otu ebumnuche ị nwere ike imezu taa!', ha: 'Kana shirye ka canza lafiyarka? Fara ta hanyar saita manufa ɗaya mai yiwuwa yau!', pcm: 'You ready to transform your health? Start by setting one achievable goal today!' },
  'goals.tipKeepOne': { en: 'Amazing work completing {n} goal! Your dedication is paying off. Keep pushing forward!', es: '¡Excelente trabajo completando {n} meta! Tu dedicación está dando frutos. ¡Sigue adelante!', fr: 'Excellent travail, {n} objectif terminé ! Votre dévouement porte ses fruits. Continuez !', yo: 'Iṣẹ́ àgbàyanu ni pípari àfojúsùn {n}! Ìfaramọ́ rẹ ń so èso. Máa tẹ̀síwájú!', ig: 'Ọrụ magburu onwe ya imecha ebumnuche {n}! Nraranye gị na-amị mkpụrụ. Nọgide na-aga n\'ihu!', ha: "Aiki mai ban mamaki na kammala manufa {n}! Kwazonka yana ba da 'ya'ya. Ci gaba da turawa!", pcm: 'Amazing work as you complete {n} goal! Your dedication dey pay off. Keep pushing forward!' },
  'goals.tipKeepMany': { en: 'Amazing work completing {n} goals! Your dedication is paying off. Keep pushing forward!', es: '¡Excelente trabajo completando {n} metas! Tu dedicación está dando frutos. ¡Sigue adelante!', fr: 'Excellent travail, {n} objectifs terminés ! Votre dévouement porte ses fruits. Continuez !', yo: 'Iṣẹ́ àgbàyanu ni pípari àwọn àfojúsùn {n}! Ìfaramọ́ rẹ ń so èso. Máa tẹ̀síwájú!', ig: 'Ọrụ magburu onwe ya imecha ebumnuche {n}! Nraranye gị na-amị mkpụrụ. Nọgide na-aga n\'ihu!', ha: "Aiki mai ban mamaki na kammala manufofi {n}! Kwazonka yana ba da 'ya'ya. Ci gaba da turawa!", pcm: 'Amazing work as you complete {n} goals! Your dedication dey pay off. Keep pushing forward!' },
  'goals.tipSimple': { en: 'Break big goals into smaller weekly targets. Small wins add up!', es: 'Divide las metas grandes en objetivos semanales más pequeños. ¡Las pequeñas victorias suman!', fr: 'Divisez les grands objectifs en cibles hebdomadaires plus petites. Les petites victoires comptent !', yo: 'Pín àwọn àfojúsùn ńlá sí àwọn àfojúsùn ọ̀sọ̀ọ̀sẹ̀ kékeré. Àwọn ìṣẹ́gun kékeré ń kójọ!', ig: 'Kewaa nnukwu ebumnuche ka ọ bụrụ obere ihe mgbaru kwa izu. Obere mmeri na-agbakọ!', ha: 'Raba manyan manufofi zuwa ƙananan hedafofin mako. Ƙananan nasarori suna taruwa!', pcm: 'Break big goals into smaller weekly targets. Small wins dey add up!' },
  'goals.tipExpert': { en: 'Implement progressive overload: increase weekly targets by 5-10% for sustainable adaptation and adherence.', es: 'Aplica sobrecarga progresiva: aumenta los objetivos semanales un 5-10% para una adaptación y adherencia sostenibles.', fr: "Appliquez la surcharge progressive : augmentez les objectifs hebdomadaires de 5 à 10 % pour une adaptation et une adhésion durables.", yo: 'Lo ìwúwo ìtẹ̀síwájú: mú àwọn àfojúsùn ọ̀sọ̀ọ̀sẹ̀ pọ̀ sí i ní 5-10% fún ìbámu àti ìfaramọ́ tí ó dúró pẹ́.', ig: 'Jiri ibu na-aga n\'ihu: welie ebumnuche kwa izu site na 5-10% maka mmegharị na nnọgide na-adigide.', ha: 'Aiwatar da ƙarin nauyi a hankali: ƙara manufofin mako da kashi 5-10% don daidaitawa mai dorewa.', pcm: 'Implement progressive overload: increase weekly targets by 5-10% for sustainable adaptation and adherence.' },
  'goals.addDesc': { en: 'Set a new health goal to track your progress', es: 'Establece una nueva meta de salud para seguir tu progreso', fr: 'Définissez un nouvel objectif santé pour suivre votre progrès', yo: 'Gbé àfojúsùn ìlera tuntun kalẹ̀ láti tọpа ìtẹ̀síwájú rẹ', ig: 'Tọọ ebumnuche ahụike ọhụrụ iji soro ọganihu gị', ha: 'Saita sabuwar manufar lafiya don bibiyar ci gaba', pcm: 'Set a new health goal to track your progress' },
  'goals.goalTitle': { en: 'Goal Title', es: 'Título de la meta', fr: "Titre de l'objectif", yo: 'Àkọlé Àfojúsùn', ig: 'Aha Ebumnuche', ha: 'Sunan Manufa', pcm: 'Goal Title' },
