  'goals.editDesc': { en: 'Update your goal details', es: 'Actualiza los detalles de tu meta', fr: 'Mettez à jour les détails de votre objectif', yo: 'Ṣàtúnṣe àwọn àlàyé àfojúsùn rẹ', ig: 'Melite nkọwa ebumnuche gị', ha: 'Sabunta bayanan manufarka', pcm: 'Update your goal details' },
  'goals.currentProgress': { en: 'Current Progress', es: 'Progreso actual', fr: 'Progrès actuel', yo: 'Ìtẹ̀síwájú Lọ́wọ́lọ́wọ́', ig: 'Ọganihu Ugbu a', ha: 'Ci gaba na Yanzu', pcm: 'Current Progress' },
