  'goals.progressGain': { en: '+{d} {unit} progress!', es: '¡+{d} {unit} de progreso!', fr: '+{d} {unit} de progrès !', yo: '+{d} {unit} ìtẹ̀síwájú!', ig: '+{d} {unit} ọganihu!', ha: '+{d} {unit} ci gaba!', pcm: '+{d} {unit} progress!' },
