  'goals.updateProgressDesc': { en: 'Update your current value for "{title}"', es: 'Actualiza tu valor actual para «{title}»', fr: 'Mettez à jour votre valeur actuelle pour « {title} »', yo: 'Ṣàtúnṣe iye lọ́wọ́lọ́wọ́ rẹ fún "{title}"', ig: 'Melite uru gị ugbu a maka "{title}"', ha: 'Sabunta ƙimarka ta yanzu don "{title}"', pcm: 'Update your current value for "{title}"' },
  'goals.deletedMsg': { en: '"{title}" deleted', es: '«{title}» eliminada', fr: '« {title} » supprimé', yo: '"{title}" ti parẹ́', ig: 'Ehichapụla "{title}"', ha: 'An share "{title}"', pcm: '"{title}" don delete' },
  'goals.targetReachedMsg': { en: '{title} - Target Reached!', es: '{title} - ¡Objetivo alcanzado!', fr: '{title} - Objectif atteint !', yo: '{title} - Àfojúsùn Dé!', ig: '{title} - Erutela Ebumnuche!', ha: '{title} - An Cimma Manufa!', pcm: '{title} - Target Reached!' },
