  'medtrack.title': { en: 'Medication Tracker', es: 'Rastreador de medicamentos', fr: 'Suivi des médicaments', yo: 'Olùtọpа Òògùn', ig: 'Onye Nsochi Ọgwụ', ha: 'Mai Bin Magani', pcm: 'Medication Tracker' },
  'medtrack.toast.fillRequired': { en: 'Please fill in all required fields', es: 'Por favor completa todos los campos requeridos', fr: 'Veuillez remplir tous les champs obligatoires', yo: 'Jọ̀wọ́ kún gbogbo àwọn àyè tí a béèrè', ig: 'Biko dejupụta mpaghara niile achọrọ', ha: 'Da fatan cika duk filayen da ake buƙata', pcm: 'Abeg fill all the required fields' },
  'medtrack.toast.updated': { en: 'Medication updated!', es: '¡Medicamento actualizado!', fr: 'Médicament mis à jour !', yo: 'A ti ṣàtúnṣe òògùn!', ig: 'Emelitela ọgwụ!', ha: 'An sabunta magani!', pcm: 'Medication don update!' },
