  'medtrack.toast.deleted': { en: 'Medication deleted', es: 'Medicamento eliminado', fr: 'Médicament supprimé', yo: 'A ti pa òògùn rẹ́', ig: 'Ehichapụla ọgwụ', ha: 'An share magani', pcm: 'Medication don delete' },
  'medtrack.toast.logged': { en: '{name} logged!', es: '¡{name} registrado!', fr: '{name} enregistré !', yo: 'A ti kọ {name} sílẹ̀!', ig: 'Edeela {name}!', ha: 'An rubuta {name}!', pcm: '{name} don log!' },
  'medtrack.toast.criticalToast': { en: 'Critical: {name} - Only {n} pills left!', es: 'Crítico: {name} - ¡Solo quedan {n} pastillas!', fr: 'Critique : {name} - Plus que {n} comprimés !', yo: 'Pàjáwìrì: {name} - Àwọn ìṣù {n} péré ló kù!', ig: 'Ihe egwu: {name} - Naanị mkpịsị {n} fọdụrụ!', ha: 'Gaggawa: {name} - Kwaya {n} kawai suka rage!', pcm: 'Critical: {name} - Na only {n} pills remain!' },
  'medtrack.confirmDelete': { en: 'Are you sure you want to delete this medication?', es: '¿Seguro que quieres eliminar este medicamento?', fr: 'Voulez-vous vraiment supprimer ce médicament ?', yo: 'Ṣé o dá ọ lójú pé o fẹ́ pa òògùn yìí rẹ́?', ig: "Ị ji n'aka na ị chọrọ ihichapụ ọgwụ a?", ha: 'Ka tabbata kana son share wannan magani?', pcm: 'You sure say you wan delete this medication?' },
  'medtrack.alertCriticalTitle': { en: 'Critical: {name} Running Low', es: 'Crítico: {name} se está agotando', fr: 'Critique : {name} bientôt épuisé', yo: 'Pàjáwìrì: {name} ń parí', ig: 'Ihe egwu: {name} na-agwụ', ha: 'Gaggawa: {name} yana ƙarewa', pcm: 'Critical: {name} dey finish' },
  'medtrack.alertCriticalDesc': { en: 'Only {n} pills remaining. Order refill immediately!', es: 'Solo quedan {n} pastillas. ¡Pide reposición de inmediato!', fr: 'Plus que {n} comprimés. Commandez un réapprovisionnement immédiatement !', yo: 'Àwọn ìṣù {n} péré ló kù. Bèèrè fún àfikún lẹ́sẹ̀kẹsẹ̀!', ig: 'Naanị mkpịsị {n} fọdụrụ. Nyefee refill ozugbo!', ha: 'Kwaya {n} kawai suka rage. Ka nemi ƙari nan da nan!', pcm: 'Na only {n} pills remain. Order refill sharp sharp!' },
  'medtrack.interactionTitle': { en: 'Interaction: {combo}', es: 'Interacción: {combo}', fr: 'Interaction : {combo}', yo: 'Ìbáṣepọ̀: {combo}', ig: 'Mmekọrịta: {combo}', ha: 'Hulɗa: {combo}', pcm: 'Interaction: {combo}' },
  'medtrack.adherence7Day': { en: '7-Day Adherence', es: 'Cumplimiento de 7 días', fr: 'Observance sur 7 jours', yo: 'Ìfaramọ́ Ọjọ́ 7', ig: 'Nnọgide Ụbọchị 7', ha: "Bin Ƙa'ida na Kwana 7", pcm: '7-Day Adherence' },
  'medtrack.adh.excellent': { en: 'Excellent!', es: '¡Excelente!', fr: 'Excellent !', yo: 'Dáradára gan!', ig: 'Magburu onwe ya!', ha: 'Kyakkyawa!', pcm: 'Excellent!' },
