  'medtrack.adh.needsImprovement': { en: 'Needs Improvement', es: 'Necesita mejorar', fr: 'À améliorer', yo: 'Nílò Ìlọsíwájú', ig: 'Chọrọ Nkwalite', ha: 'Yana Buƙatar Ingantawa', pcm: 'Need Improvement' },
  'medtrack.todaySchedule': { en: "Today's Schedule", es: 'Horario de hoy', fr: 'Programme du jour', yo: 'Ètò Òní', ig: 'Nhazi Taa', ha: 'Jadawalin Yau', pcm: 'Today Schedule' },
  'medtrack.noDoses': { en: 'No scheduled doses for today', es: 'No hay dosis programadas para hoy', fr: "Aucune dose programmée pour aujourd'hui", yo: 'Kò sí ìwọ̀n òògùn tí a ṣètò fún òní', ig: 'Enweghị ọgwụ e mere atụmatụ maka taa', ha: 'Babu allurar da aka tsara na yau', pcm: 'No dose dey scheduled for today' },
