  'medtrack.activeMeds': { en: 'Active Medications', es: 'Medicamentos activos', fr: 'Médicaments actifs', yo: 'Àwọn Òògùn Tó Ń Ṣiṣẹ́', ig: 'Ọgwụ Ndị Na-arụ Ọrụ', ha: 'Magungunan da ke Aiki', pcm: 'Active Medications' },
  'medtrack.emptyTitle': { en: 'No medications added yet', es: 'Aún no se han añadido medicamentos', fr: "Aucun médicament ajouté pour l'instant", yo: 'Kò sí òògùn tí a fikun síbẹ̀', ig: 'Enwebeghị ọgwụ agbakwunyere', ha: 'Ba a ƙara magunguna tukuna', pcm: 'No medication dey yet' },
  'medtrack.emptySubtitle': { en: 'Track your medications, supplements and vitamins to get dose reminders and refill alerts.', es: 'Registra tus medicamentos, suplementos y vitaminas para recibir recordatorios de dosis y alertas de reposición.', fr: 'Suivez vos médicaments, compléments et vitamines pour recevoir des rappels de dose et des alertes de réapprovisionnement.', yo: 'Tọpа àwọn òògùn, àfikún àti fítámì rẹ láti gba ìránilétí ìwọ̀n àti ìkìlọ̀ àfikún.', ig: 'Soro ọgwụ, mgbakwunye na vitamin gị iji nweta ncheta ọgwụ na ọkwa refill.', ha: 'Bibiyar magungunanka, ƙarin abinci da bitamin don samun tunatarwar allura da faɗakarwar ƙari.', pcm: 'Track your medications, supplements and vitamins to get dose reminders and refill alerts.' },
  'medtrack.addFirst': { en: 'Add First Medication', es: 'Añadir primer medicamento', fr: 'Ajouter le premier médicament', yo: 'Fi Òògùn Àkọ́kọ́ Kún', ig: 'Tinye Ọgwụ Mbụ', ha: 'Ƙara Magani na Farko', pcm: 'Add First Medication' },
  'medtrack.stockRemaining': { en: 'Stock Remaining', es: 'Existencias restantes', fr: 'Stock restant', yo: 'Ọjà Tó Kù', ig: 'Ihe Fọdụrụ', ha: 'Sauran Kaya', pcm: 'Stock Remaining' },
  'medtrack.pillsDays': { en: '{n} pills ({d} days)', es: '{n} pastillas ({d} días)', fr: '{n} comprimés ({d} jours)', yo: 'Ìṣù {n} (ọjọ́ {d})', ig: 'Mkpịsị {n} (ụbọchị {d})', ha: 'Kwaya {n} (kwana {d})', pcm: '{n} pills ({d} days)' },
  'medtrack.orderNow': { en: 'Order refill immediately!', es: '¡Pide reposición de inmediato!', fr: 'Commandez un réapprovisionnement immédiatement !', yo: 'Bèèrè fún àfikún lẹ́sẹ̀kẹsẹ̀!', ig: 'Nyefee refill ozugbo!', ha: 'Ka nemi ƙari nan da nan!', pcm: 'Order refill sharp sharp!' },
  'medtrack.refillSoon': { en: 'Time to refill soon', es: 'Pronto habrá que reponer', fr: "Bientôt l'heure de réapprovisionner", yo: 'Ó tó àkókò láti fi kún láìpẹ́', ig: 'Oge iji refill na-abịaru nso', ha: 'Lokacin ƙari ya kusa', pcm: 'E soon reach time to refill' },
  'medtrack.bestPractices': { en: 'Medication Best Practices', es: 'Buenas prácticas con medicamentos', fr: 'Bonnes pratiques médicamenteuses', yo: 'Àwọn Àṣà Òògùn Tó Dára Jù', ig: 'Omume Kacha Mma nke Ọgwụ', ha: 'Mafi Kyawun Halaye na Magani', pcm: 'Medication Best Practices' },
  'medtrack.tip1Title': { en: 'Consistency is Key', es: 'La constancia es clave', fr: 'La régularité est essentielle', yo: 'Ìdúróṣinṣin ni Kọ́kọ́rọ́', ig: 'Nkwụsi ike bụ Isi', ha: 'Daidaito shine Mabuɗi', pcm: 'Consistency na Key' },
  'medtrack.tip1Desc': { en: 'Take medications at the same time daily for optimal effectiveness.', es: 'Toma los medicamentos a la misma hora cada día para una eficacia óptima.', fr: 'Prenez vos médicaments à la même heure chaque jour pour une efficacité optimale.', yo: 'Mu àwọn òògùn ní àkókò kan náà lójoojúmọ́ fún àbájáde tó dára jù.', ig: 'Ṅụọ ọgwụ n\'otu oge kwa ụbọchị maka irè kacha mma.', ha: 'Sha magunguna a lokaci ɗaya kowace rana don ingantaccen sakamako.', pcm: 'Take medications at the same time every day for best effect.' },
  'medtrack.tip2Title': { en: 'Timing Matters', es: 'El momento importa', fr: 'Le moment compte', yo: 'Àkókò Ṣe Pàtàkì', ig: 'Oge Dị Mkpa', ha: 'Lokaci Yana da Muhimmanci', pcm: 'Timing Matter' },
  'medtrack.tip2Desc': { en: 'Some supplements work better on empty stomach, others with food.', es: 'Algunos suplementos funcionan mejor con el estómago vacío, otros con comida.', fr: "Certains compléments agissent mieux à jeun, d'autres avec de la nourriture.", yo: 'Àwọn àfikún kan ń ṣiṣẹ́ dáradára nígbà tí ikùn bá ṣófo, àwọn míì pẹ̀lú oúnjẹ.', ig: 'Ụfọdụ mgbakwunye na-arụ ọrụ nke ọma mgbe afọ tọgbọrọ chakoo, ndị ọzọ na nri.', ha: 'Wasu ƙarin abinci suna aiki da kyau a kan komai a ciki, wasu da abinci.', pcm: 'Some supplements dey work better on empty stomach, others with food.' },
  'medtrack.tip3Title': { en: 'Check Interactions', es: 'Verifica las interacciones', fr: 'Vérifiez les interactions', yo: 'Ṣàyẹ̀wò Àwọn Ìbáṣepọ̀', ig: 'Lelee Mmekọrịta', ha: 'Duba Hulɗa', pcm: 'Check Interactions' },
  'medtrack.tip3Desc': { en: 'Always consult your doctor about potential medication interactions.', es: 'Consulta siempre a tu médico sobre posibles interacciones medicamentosas.', fr: 'Consultez toujours votre médecin sur les interactions médicamenteuses possibles.', yo: 'Nígbà gbogbo, kan sí dókítà rẹ nípa àwọn ìbáṣepọ̀ òògùn tó ṣeéṣe.', ig: 'Mgbe niile gakwuru dọkịta gị maka mmekọrịta ọgwụ nwere ike ime.', ha: 'Kullum ka tuntuɓi likitanka game da yiwuwar hulɗar magunguna.', pcm: 'Always consult your doctor about possible medication interactions.' },
  'medtrack.editTitle': { en: 'Edit Medication', es: 'Editar medicamento', fr: 'Modifier le médicament', yo: 'Ṣàtúnṣe Òògùn', ig: 'Dezie Ọgwụ', ha: 'Gyara Magani', pcm: 'Edit Medication' },
  'medtrack.addTitle': { en: 'Add Medication', es: 'Añadir medicamento', fr: 'Ajouter un médicament', yo: 'Fi Òògùn Kún', ig: 'Tinye Ọgwụ', ha: 'Ƙara Magani', pcm: 'Add Medication' },
  'medtrack.editDesc': { en: 'Update medication details and dosage information.', es: 'Actualiza los detalles del medicamento y la información de dosis.', fr: 'Mettez à jour les détails du médicament et la posologie.', yo: 'Ṣàtúnṣe àwọn àlàyé òògùn àti ìsọfúnni ìwọ̀n.', ig: 'Melite nkọwa ọgwụ na ozi ọ̀tụ̀tụ̀.', ha: 'Sabunta bayanan magani da adadin sha.', pcm: 'Update medication details and dosage info.' },
  'medtrack.addDesc': { en: 'Add a new medication, supplement, or vitamin to track.', es: 'Añade un nuevo medicamento, suplemento o vitamina para registrar.', fr: 'Ajoutez un nouveau médicament, complément ou vitamine à suivre.', yo: 'Fi òògùn, àfikún, tàbí fítámì tuntun kún láti tọpа.', ig: 'Tinye ọgwụ, mgbakwunye, ma ọ bụ vitamin ọhụrụ ị ga-eso.', ha: 'Ƙara sabon magani, ƙarin abinci, ko bitamin don bibiya.', pcm: 'Add new medication, supplement, or vitamin to track.' },
